// This template is from P5js shader tutorial at
// https://itp-xstory.github.io/p5js-shaders/#/./docs/examples/basic_gradient
let theShader;
let f;

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/1574301/files/vert.glsl', 'frag.glsl');
	f = loadFont(
    "https://cdnjs.cloudflare.com/ajax/libs/topcoat/0.8.0/font/SourceCodePro-Bold.otf"
  );
}

function setup() {
  pixelDensity(2);
  createCanvas(1000, 1000, WEBGL);
}

function draw() {
  shader(theShader);

  theShader.setUniform("u_resolution", [width*2, height*2]);
  theShader.setUniform("u_time", millis() / 1000.0);

	stroke(255, 234, 249);
	strokeWeight(50);
  rect(width * -0.5, height * -0.5, width, height);

	push();
	resetShader();
	fill(255, 234, 249);
	stroke(0, 76, 61);
	strokeWeight(2);
	translate(0, 0, 100);
	rotateX(millis() * 0.0025 * 0.1);
	rotateY(millis() * 0.005 * 0.1);
	box(width / 10);
	pop();

	push();
	translate(0, 0, 200);
	stroke(255, 234, 249);
	strokeWeight(20);
	fill(0, 76, 61);
  textFont(f);
  textSize(40);
	textAlign(CENTER, CENTER);
	const t = "(out of bounds)";
	text(t, -2, 0);
	text(t, 0, -2);
	text(t, 2, 0);
	text(t, 0, 2);
	fill(255, 234, 249);
	text(t, 0, 0);
	pop();
}


// === Tab: frag.glsl ===
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;

float rand(vec2 co){
  return fract(sin(dot(co.xy,vec2(12.9898,78.233))) * 43758.5453);
}

void main() {
	vec2 uv = gl_FragCoord.xy/u_resolution.xy;

	uv += vec2(-.05, -.3);
	uv.y /= uv.x * 2.;

	vec2 center_uv = uv - .5;

	float c = length(center_uv) * 100.;
	c = sin(-1. * u_time + c) / 2. + .5;
	c += rand(uv) / 2. - .25;
	c = step(.5, c);

	float c2 = length(center_uv) * 13.;
	c2 = fract(-0.1 * u_time + c2);
	c2 += rand(uv) / 2. - .25;
	c2 = step(.5, c2);

	c = c + c2 - 2.*c*c2; //xor

	vec3 color1 = vec3(1., .92, .98);
	vec3 color2 = vec3(0., .3, .24);
	vec3 col = mix(color1, color2, c);

  gl_FragColor = vec4(col,1.0); 
}

